import{_ as a,o as t,c as s,a0 as o}from"./chunks/framework.tVbs9ddD.js";const p=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),n={name:"explanation/decisions.md"};function r(i,e,d,c,l,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite — the decisions that shape kuda, the alternatives rejected, and the consequence each carries. Full history lives in git and the org ledger (<code>project/</code>).</p><h2 id="cards-are-committed-the-graph-is-not" tabindex="-1">Cards are committed; the graph is not <a class="header-anchor" href="#cards-are-committed-the-graph-is-not" aria-label="Permalink to &quot;Cards are committed; the graph is not&quot;">​</a></h2><p><strong>Decision:</strong> L0/L1 YAML cards are committed artifacts reviewed in diffs; the L2 sqlite graph is gitignored and rebuildable.</p><p><strong>Alternatives:</strong> commit everything (the graph churns every sync — noise that drowns the prose); commit nothing (cards become derived state nobody reviews, and provenance stops meaning anything).</p><p><strong>Consequence:</strong> cards are <em>claims with evidence</em> — humans and <code>mimus audit</code> can falsify them. The graph is free to be a cache.</p><h2 id="modules-group-by-manifest-package-not-directory" tabindex="-1">Modules group by manifest package, not directory <a class="header-anchor" href="#modules-group-by-manifest-package-not-directory" aria-label="Permalink to &quot;Modules group by manifest package, not directory&quot;">​</a></h2><p><strong>Decision:</strong> extraction groups source files by the package name declared in <code>Cargo.toml</code>/<code>package.json</code>/<code>pyproject.toml</code>, falling back to directories only when no manifest exists.</p><p><strong>Alternatives:</strong> directory grouping (splits one crate across <code>src/</code>, <code>tests/</code>, <code>benches/</code> into fake &quot;modules&quot; and merges unrelated dirs that happen to share a parent); repo-wide flat indexing (no module boundary = no place to hang an L1 card).</p><p><strong>Consequence:</strong> <code>docs/</code> (a git worktree) indexes as its own package <code>kuda-docs</code>; workspace members stay distinct even when they share a directory tree.</p><h2 id="language-knowledge-is-data-not-code" tabindex="-1">Language knowledge is data, not code <a class="header-anchor" href="#language-knowledge-is-data-not-code" aria-label="Permalink to &quot;Language knowledge is data, not code&quot;">​</a></h2><p><strong>Decision:</strong> per-language grammars, symbol queries, and manifest names live in <code>data/langs/*</code>; extractor code only knows the adapter vocabulary (<code>SymbolKind</code>, <code>EdgeKind</code>).</p><p><strong>Alternatives:</strong> per-language extractor crates (a release per language, adapter sprawl); tree-sitter-only (no package-graph signal — the free <code>manifest</code> tier disappears).</p><p><strong>Consequence:</strong> adding a language is a data change reviewable in a diff — see <a href="./../how-to/languages.html">adding a language</a>. The cost is a small descriptor DSL the extractors must interpret.</p><h2 id="sync-is-hash-gated-end-to-end" tabindex="-1">Sync is hash-gated end to end <a class="header-anchor" href="#sync-is-hash-gated-end-to-end" aria-label="Permalink to &quot;Sync is hash-gated end to end&quot;">​</a></h2><p><strong>Decision:</strong> every file gets an in-process git blob hash compared against the store; unchanged modules are never re-parsed and cards with matching provenance are reused verbatim — including skipping the summarizer/agent entirely.</p><p><strong>Alternatives:</strong> mtime-based staleness (unreliable across checkouts and rebases); always-resummarize (agent spend per sync instead of per drift).</p><p><strong>Consequence:</strong> steady-state sync is sub-second and agent spend scales with <em>change</em>, not repo size. The <code>files</code> table in sqlite is the source of truth for &quot;did this file change.&quot;</p><h2 id="the-release-seed-is-explicit" tabindex="-1">The release seed is explicit <a class="header-anchor" href="#the-release-seed-is-explicit" aria-label="Permalink to &quot;The release seed is explicit&quot;">​</a></h2><p><strong>Decision:</strong> the first <code>cargo publish</code> of the workspace is a hand-run <code>kuda deploy release</code>; every release after that is an ordinary push-driven job.</p><p><strong>Alternatives:</strong> fully automatic publishing on every merge (a half-published workspace or a wrong tag is forever on crates.io); release-plz/GHA (hosted CI for a project whose point is that CI is a local loop).</p><p><strong>Consequence:</strong> the only irreversible step in the system gets a human at the gate; everything else is idempotent and local. See <a href="./release-model.html">the release model</a>.</p>',22)])])}const m=a(n,[["render",r]]);export{p as __pageData,m as default};
